BEGIN;

VALUES ('HAF', '{"source_key":"HAF","name":"Hope and Fear","short_title":"H&F"}', 1, unixepoch() * 1000, unixepoch() * 1000, NULL)
ON CONFLICT(source_key) DO UPDATE SET
  metadata = excluded.metadata,
  enabled = 1,
  updated_at = unixepoch() * 1000,
  deleted_at = NULL;

CREATE TEMP TABLE _haf_adversaries (
  item_type TEXT NOT NULL,
  item_id TEXT NOT NULL,
  item TEXT NOT NULL,
  PRIMARY KEY (item_type, item_id)
);


SELECT item_type, item_id, 'HAF', 1, unixepoch() * 1000, unixepoch() * 1000, NULL
FROM _haf_adversaries
WHERE true
ON CONFLICT(source_key, item_type, item_id) DO UPDATE SET
  current_version = 1,
  updated_at = unixepoch() * 1000,
  deleted_at = NULL;

SELECT item_type, item_id, 'HAF', 1, 'v1', 'Initial Hope and Fear import.', item, unixepoch() * 1000, unixepoch() * 1000, NULL
FROM _haf_adversaries
WHERE true
ON CONFLICT(source_key, item_type, item_id, item_version) DO UPDATE SET
  label = excluded.label,
  changelog = excluded.changelog,
  item = excluded.item,
  published_at = unixepoch() * 1000,
  deleted_at = NULL;

DROP TABLE _haf_adversaries;

UPDATE official_compendium_items
SET updated_at = unixepoch() * 1000,
    deleted_at = coalesce(deleted_at, unixepoch() * 1000)
WHERE source_key = 'HAF'
  AND item_type = 'adversaries'
  AND item_id IN ('doppelhund', 'shadow_king', 'xero_castle_killer');

UPDATE official_compendium_item_versions
SET deleted_at = coalesce(deleted_at, unixepoch() * 1000)
WHERE source_key = 'HAF'
  AND item_type = 'adversaries'
  AND item_id IN ('doppelhund', 'shadow_king', 'xero_castle_killer');

COMMIT;
